<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$msg='';$error='';$settings=$db->query('SELECT * FROM crm_automation_settings WHERE id=1')->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){$enabled=isset($_POST['enabled'])?1:0;$auto=isset($_POST['auto_score'])?1:0;$rh=max(1,(int)($_POST['reminder_hours']??24));$ih=max(1,(int)($_POST['initial_followup_hours']??24));$pd=max(1,(int)($_POST['proposal_followup_days']??3));$nr=max(1,(int)($_POST['no_response_days']??5));$db->prepare('UPDATE crm_automation_settings SET enabled=?,auto_score=?,reminder_hours=?,initial_followup_hours=?,proposal_followup_days=?,no_response_days=? WHERE id=1')->execute([$enabled,$auto,$rh,$ih,$pd,$nr]);$settings=$db->query('SELECT * FROM crm_automation_settings WHERE id=1')->fetch();$msg='Automation settings saved.';}$pending=$db->query("SELECT f.*,l.name,l.email,l.service,l.status FROM lead_followups f JOIN leads l ON l.id=f.lead_id WHERE f.status='pending' ORDER BY f.scheduled_at ASC LIMIT 50")->fetchAll();$logs=$db->query('SELECT a.*,l.name FROM automation_logs a LEFT JOIN leads l ON l.id=a.lead_id ORDER BY a.created_at DESC LIMIT 20')->fetchAll();$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$dt=static fn($v):string=>$v?date('d M Y, H:i',strtotime((string)$v)):'—';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CRM Automation</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:1100px"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2">CRM Automation</h1><p class="text-muted">Follow-up rules, lead scoring and automation queue</p></div><a href="crm-dashboard.php" class="btn btn-outline-dark">CRM Dashboard</a></div><?php if($msg):?><div class="alert alert-success"><?=$esc($msg)?></div><?php endif;?><div class="row g-4"><div class="col-lg-5"><div class="card border-0 shadow-sm p-4"><h2 class="h5">Automation Settings</h2><form method="post"><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" name="enabled" id="enabled" <?=$settings['enabled']?'checked':''?>><label class="form-check-label" for="enabled">Enable automation</label></div><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" name="auto_score" id="auto_score" <?=$settings['auto_score']?'checked':''?>><label class="form-check-label" for="auto_score">Automatic lead scoring</label></div><label class="form-label">Admin reminder hours</label><input type="number" min="1" name="reminder_hours" class="form-control mb-3" value="<?=$esc($settings['reminder_hours'])?>"><label class="form-label">Initial follow-up hours</label><input type="number" min="1" name="initial_followup_hours" class="form-control mb-3" value="<?=$esc($settings['initial_followup_hours'])?>"><label class="form-label">Proposal follow-up days</label><input type="number" min="1" name="proposal_followup_days" class="form-control mb-3" value="<?=$esc($settings['proposal_followup_days'])?>"><label class="form-label">No-response days</label><input type="number" min="1" name="no_response_days" class="form-control mb-3" value="<?=$esc($settings['no_response_days'])?>"><button class="btn btn-dark w-100">Save Settings</button></form></div></div><div class="col-lg-7"><div class="card border-0 shadow-sm p-4 mb-4"><div class="d-flex justify-content-between"><h2 class="h5">Follow-up Queue</h2><span class="badge text-bg-dark"><?=count($pending)?></span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Lead</th><th>Type</th><th>Scheduled</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($pending as $f):?><tr><td><strong><?=$esc($f['name'])?></strong><div class="small text-muted"><?=$esc($f['email'])?></div></td><td><?=ucfirst(str_replace('_',' ',$esc($f['followup_type'])))?></td><td class="<?=strtotime($f['scheduled_at'])<=time()?'text-danger fw-bold':''?>"><?=$esc($dt($f['scheduled_at']))?></td><td><span class="badge text-bg-warning">Pending</span></td><td><a class="btn btn-sm btn-outline-dark" href="lead.php?id=<?=$f['lead_id']?>">Open</a></td></tr><?php endforeach;?><?php if(!$pending):?><tr><td colspan="5" class="text-muted">No pending automated follow-ups.</td></tr><?php endif;?></tbody></table></div></div><div class="card border-0 shadow-sm p-4"><h2 class="h5">Automation Log</h2><?php foreach($logs as $l):?><div class="border-bottom py-2"><div class="d-flex justify-content-between"><strong><?=$esc($l['event_type'])?></strong><small class="text-muted"><?=$esc($dt($l['created_at']))?></small></div><div class="small text-secondary"><?=$esc($l['message'])?></div></div><?php endforeach;?><?php if(!$logs):?><p class="text-muted">No automation events yet.</p><?php endif;?></div></div></div></main></body></html>